4.2 Unit Tests
Unit tests verify that individual functions behave correctly with known inputs and expected outputs:

test_that("outlier detection works", {
  test_data &lt;- c(1, 2, 3, 100, 4, 5)
  outliers &lt;- detect_outliers(
    test_data, method = "iqr"
  )

  expect_equal(outliers, 100)
  expect_length(outliers, 1)
})

4.3 Data Validation Tests
Data validation tests ensure data meets quality requirements before analysis proceeds:

test_that("data meets quality standards", {
  data &lt;- read.csv(
    "analysis/data/raw_data/penguins.csv"
  )

  expect_equal(ncol(data), 8)
  expect_true(
    all(
      c("species", "body_mass_g") %in%
        names(data)
    )
  )
  expect_true(
    all(data$body_mass_g &gt; 0, na.rm = TRUE)
  )
  expect_true(
    all(data$body_mass_g &lt; 10000, na.rm = TRUE)
  )
})

4.4 Integration Tests
Integration tests verify that pipeline components work together:

test_that("pipeline runs successfully", {
  expect_no_error({
    raw_data &lt;- load_raw_data()
    clean_data &lt;- clean_data(raw_data)
    model &lt;- fit_model(clean_data)
    results &lt;- generate_results(model)
  })

  expect_s3_class(results, "data.frame")
  expect_true(nrow(results) &gt; 0)
})

4.6 Reproducibility Tests
Reproducibility tests confirm that results are deterministic when using the same random seed:

test_that("bootstrap is reproducible", {
  set.seed(42)
  results1 &lt;- bootstrap_analysis(
    data, n_boots = 1000
  )

  set.seed(42)
  results2 &lt;- bootstrap_analysis(
    data, n_boots = 1000
  )

  expect_equal(
    results1$estimate, results2$estimate
  )
  expect_equal(
    results1$ci_lower, results2$ci_lower
  )
})




A diagram showing the testing pyramid with unit tests at the base, integration tests in the middle, and reproducibility tests at the top


The testing pyramid for data analysis: unit tests form the broad base, integration tests provide pipeline coverage, and reproducibility tests ensure determinism.

5.4 Helper Functions
Create reusable test utilities in helper-*.R files:

create_test_penguins &lt;- function(n = 50) {
  data.frame(
    species = sample(
      c("Adelie", "Chinstrap", "Gentoo"),
      n, replace = TRUE
    ),
    bill_length_mm = rnorm(
      n, mean = 44, sd = 5
    ),
    body_mass_g = rnorm(
      n, mean = 4200, sd = 800
    )
  )
}

expect_valid_model &lt;- function(model) {
  expect_s3_class(model, "lm")
  expect_true(length(coef(model)) &gt; 0)
  expect_true(!any(is.na(coef(model))))
}

6.1 Pipeline-Friendly Assertions
The assertr package integrates data validation into tidyverse pipelines:

library(assertr)

penguins |&gt;
  verify(nrow(.) &gt; 300) |&gt;
  verify(ncol(.) == 8) |&gt;
  assert(
    within_bounds(0, 10000), body_mass_g
  ) |&gt;
  assert(
    in_set("Adelie", "Chinstrap", "Gentoo"),
    species
  ) |&gt;
  insist(within_n_sds(3), bill_length_mm)

6.3 Domain-Specific Validation
Create validation functions tailored to the data:

validate_penguin_data &lt;- function(data) {
  test_that("penguin data validation", {
    required_cols &lt;- c(
      "species", "island",
      "bill_length_mm", "bill_depth_mm",
      "flipper_length_mm", "body_mass_g",
      "sex", "year"
    )
    expect_true(
      all(required_cols %in% names(data))
    )

    valid_species &lt;- c(
      "Adelie", "Chinstrap", "Gentoo"
    )
    expect_true(
      all(data$species %in% valid_species)
    )

    expect_true(
      all(data$bill_length_mm &gt; 0,
          na.rm = TRUE)
    )
    expect_true(
      all(data$year &gt;= 2007 &
          data$year &lt;= 2009)
    )
  })
}

7.3 Package Version Testing
Track package versions to identify when results might change:

test_that("expected package versions", {
  expect_true(
    packageVersion("dplyr") &gt;= "1.0.0"
  )
  expect_true(
    packageVersion("ggplot2") &gt;= "3.4.0"
  )

  if (requireNamespace("renv", quietly = TRUE)) {
    status &lt;- renv::status()
    expect_true(status$synchronized)
  }
})

8.1 Script Execution Tests
Verify that analysis scripts run without error:

test_that("analysis scripts run", {
  scripts &lt;- c(
    "scripts/01_load_data.R",
    "scripts/02_clean_data.R",
    "scripts/03_fit_models.R",
    "scripts/04_create_figures.R"
  )

  for (script in scripts) {
    expect_true(file.exists(script))
    expect_no_error(
      source(script, local = new.env()),
      info = paste("Failed:", script)
    )
  }
})

8.2 Output Validation
Test that scripts produce expected output files:

test_that("scripts produce outputs", {
  source(
    "scripts/02_clean_data.R",
    local = new.env()
  )

  expect_true(file.exists(
    "analysis/data/derived_data/clean.rds"
  ))

  clean_data &lt;- readRDS(
    "analysis/data/derived_data/clean.rds"
  )
  expect_true(nrow(clean_data) &gt; 300)
  expect_false(any(is.na(clean_data)))
})

6.2 Recipe Specification

penguin_recipe &lt;- recipe(
  body_mass_g ~ bill_length_mm +
    bill_depth_mm + flipper_length_mm +
    species + sex + island,
  data = penguin_train
) |&gt;
  step_dummy(all_nominal_predictors()) |&gt;
  step_normalize(all_numeric_predictors())

penguin_recipe

6.3 Model Specifications
The analysis compares linear regression with regularized regression (elastic net) to see whether penalizing coefficient size improves out-of-sample performance:

lm_spec &lt;- linear_reg() |&gt;
  set_engine("lm")

glmnet_spec &lt;- linear_reg(
  penalty = tune(), mixture = tune()
) |&gt;
  set_engine("glmnet")

6.4 Workflow Creation

lm_workflow &lt;- workflow() |&gt;
  add_recipe(penguin_recipe) |&gt;
  add_model(lm_spec)

glmnet_workflow &lt;- workflow() |&gt;
  add_recipe(penguin_recipe) |&gt;
  add_model(glmnet_spec)

5.2 Input Module

inputsUI &lt;- function(id) {
  ns &lt;- NS(id)
  tagList(
    h4("Boxplot Controls"),
    add_tooltip(
      selectInput(
        ns("xvar"),
        "Continuous Variable for Boxplot:",
        choices = names(data)[3:6]
      ),
      paste0(
        "Select a continuous variable to ",
        "display on the Y-axis of the boxplot."
      )
    ),
    add_tooltip(
      selectInput(
        ns("groupvar"),
        "Group by (Categorical Variable):",
        choices = c("species", "sex", "island"),
        selected = "species"
      ),
      paste0(
        "Select a categorical variable to ",
        "group data in the boxplot."
      )
    ),
    hr(),
    h4("Scatterplot Controls"),
    add_tooltip(
      selectInput(
        ns("scatter_x"),
        "X-axis for Scatterplot:",
        choices = names(data)[3:6]
      ),
      paste0(
        "Select a variable for the X-axis ",
        "of the scatterplot."
      )
    ),
    add_tooltip(
      selectInput(
        ns("scatter_y"),
        "Y-axis for Scatterplot:",
        choices = names(data)[3:6]
      ),
      paste0(
        "Select a variable for the Y-axis ",
        "of the scatterplot."
      )
    ),
    add_tooltip(
      selectInput(
        ns("groupvar_scatter"),
        "Group by (Scatterplot):",
        choices = c("species", "sex", "island"),
        selected = "species"
      ),
      paste0(
        "Select a variable to group points ",
        "in the scatterplot by color."
      )
    )
  )
}

inputsServer &lt;- function(id) {
  moduleServer(id, function(input, output, session) {
    reactive(input)
  })
}

The input module consolidates all user controls into a single namespace. The inputsServer function returns a reactive reference to the entire input object, which other modules consume.

5.3 Boxplot Module

boxplotUI &lt;- function(id) {
  ns &lt;- NS(id)
  plotOutput(ns("boxPlot"), height = "400px")
}

boxplotServer &lt;- function(id, data, inputs) {
  moduleServer(
    id, function(input, output, session) {
    output$boxPlot &lt;- renderPlot({
      req(data(), inputs())
      ggplot(
        data(),
        aes(
          x = .data[[inputs()$groupvar]],
          y = .data[[inputs()$xvar]],
          fill = .data[[inputs()$groupvar]]
        )
      ) +
        geom_boxplot(alpha = 0.7) +
        theme_minimal() +
        labs(
          x = inputs()$groupvar,
          y = inputs()$xvar,
          fill = inputs()$groupvar
        ) +
        theme(legend.position = "bottom")
    })
  })
}

The boxplot module uses .data[[]] pronoun syntax for tidy evaluation, which is the correct approach for programmatic column selection in ggplot2. This is one area where ChatGPT produced idiomatic code without correction.

5.4 Scatterplot Module

scatterplotUI &lt;- function(id) {
  ns &lt;- NS(id)
  plotOutput(
    ns("scatterPlot"), height = "400px"
  )
}

scatterplotServer &lt;- function(id, data, inputs) {
  moduleServer(
    id, function(input, output, session) {
    output$scatterPlot &lt;- renderPlot({
      req(data(), inputs())
      ggplot(
        data(),
        aes(
          x = .data[[inputs()$scatter_x]],
          y = .data[[inputs()$scatter_y]],
          color = .data[[
            inputs()$groupvar_scatter
          ]]
        )
      ) +
        geom_point(alpha = 0.7, size = 2) +
        geom_smooth(
          method = "lm",
          se = FALSE,
          aes(group = 1),
          color = "black",
          linetype = "dashed"
        ) +
        geom_smooth(
          method = "lm", se = FALSE
        ) +
        theme_minimal() +
        labs(
          x = inputs()$scatter_x,
          y = inputs()$scatter_y,
          color = inputs()$groupvar_scatter
        ) +
        theme(legend.position = "bottom")
    })
  })
}

The scatterplot module includes two trend lines: a dashed black line for the overall relationship and coloured lines for each group. This dual-trend approach was generated by ChatGPT in response to the third prompt.

5.5 Correlation Module

correlationUI &lt;- function(id) {
  ns &lt;- NS(id)
  plotOutput(
    ns("correlationMatrix"), height = "400px"
  )
}

correlationServer &lt;- function(id, data) {
  moduleServer(
    id, function(input, output, session) {
    output$correlationMatrix &lt;- renderPlot({
      req(data())
      numericData &lt;- data()[
        , sapply(data(), is.numeric)
      ]
      corrgram(
        numericData,
        order = TRUE,
        lower.panel = panel.shade,
        upper.panel = panel.pie,
        text.panel = panel.txt,
        main = "Correlation Matrix"
      )
    })
  })
}

The correlation module was generated as part of the first prompt response. It uses the corrgram package for visual correlation display. Note that this module does not take the inputs argument because the correlation matrix displays all numeric variables regardless of user selection.

6.1 Random Forest Importance

rf_imp &lt;- varImp(cv_rf)$importance |&gt;
  rownames_to_column("Variable") |&gt;
  arrange(desc(Overall)) |&gt;
  head(6)

kable(
  rf_imp,
  digits = 1,
  col.names = c("Variable", "Importance"),
  caption = "Variable importance scores from the
    random forest (permutation-based)."
)

6.2 Linear Model Coefficients

linear_coefs &lt;- tidy(
  cv_linear$finalModel, conf.int = TRUE
) |&gt;
  filter(term != "(Intercept)") |&gt;
  mutate(
    abs_effect = abs(estimate)
  ) |&gt;
  arrange(desc(abs_effect)) |&gt;
  select(term, estimate, conf.low, conf.high)

kable(
  linear_coefs,
  digits = 1,
  col.names = c(
    "Term", "Estimate",
    "95% CI Lower", "95% CI Upper"
  ),
  caption = "Linear model coefficients ranked by
    absolute effect size."
)

Both models agree that flipper length and species are the most important determinants of body mass. The linear model additionally provides the direction and magnitude of each effect (e.g., each millimetre of flipper length adds approximately 15-20 grams), which the random forest importance scores alone cannot convey.

4.1 The Side-by-Side Comparison
Below are two identical visualisations: one built with Observable JS (client-side) and one with Shiny (server-side). Both filter the Palmer Penguins dataset by bill length and display a histogram of body mass.


4.1.1 Observable JS

viewof bill_min_ojs = Inputs.range(
  [32, 50],
  {value: 35, step: 1,
   label: "Min bill length (mm):"}
)

penguins_raw = {
  const response = await fetch(
    "https://raw.githubusercontent.com/" +
    "allisonhorst/palmerpenguins/" +
    "main/inst/extdata/penguins.csv"
  );
  const text = await response.text();
  return d3.csvParse(text, d3.autoType);
}

data_ojs = penguins_raw.filter(
  d =&gt; d.bill_length_mm != null &&
       d.body_mass_g != null
)

filtered_ojs = data_ojs.filter(
